    const esm=[
      'https://cdn.jsdelivr.net/npm/pptx-preview@1.0.7/dist/pptx-preview.es.js',
      'https://unpkg.com/pptx-preview@1.0.7/dist/pptx-preview.es.js',
      'https://esm.sh/pptx-preview@1.0.7'
    ];
    for(const u of esm){
      try{
        const mod=await import(u);
        const init=mod.init || (mod.default && mod.default.init);
        if(typeof init==='function'){ cwPptLib={init:init}; return cwPptLib; }
      }catch(e){}
    }
    const umd=[
      'https://cdn.jsdelivr.net/npm/pptx-preview@1.0.7/dist/pptx-preview.umd.js',
      'https://unpkg.com/pptx-preview@1.0.7/dist/pptx-preview.umd.js'
    ];
    for(const u of umd){
      try{
        await new Promise(function(res,rej){
