    const loading=document.getElementById('cw-ppt-loading');
    const fallback=document.getElementById('cw-ppt-fallback');
    const title=document.getElementById('cw-ppt-title');
    const status=document.getElementById('cw-ppt-status');
    const token=++cwPptViewerToken;

    cwCurrentPptMessage=m;
    title.textContent=m.name||'PowerPoint';
    status.textContent='';
    pages.innerHTML='';
    fallback.hidden=true;
    viewer.classList.remove('ppt-rendered','ppt-error');
    loading.style.display='flex';
    viewer.classList.add('open');
    viewer.setAttribute('aria-hidden','false');

    /* Old binary .ppt / .odp cannot be rendered in the browser. Still opens inside
