      const fallback=document.getElementById('cw-pdf-fallback');
      cwCurrentPdfUrl=m.src;
      pages.innerHTML='';
      viewer.classList.remove('pdf-rendered');
      frame.style.display='none'; obj.style.display='none'; fallback.style.display='none';
      loading.style.display='flex'; viewer.classList.add('open');
      try{
        const res=await fetch(m.src);
