    cwCurrentPdfUrl=m.src;
    const token=window.__cwPdfToken=(window.__cwPdfToken||0)+1;
    const viewer=document.getElementById('cw-pdf-viewer'),
          title=document.getElementById('cw-pdf-title'),
          pages=document.getElementById('cw-pdf-pages'),
          loading=document.getElementById('cw-pdf-loading'),
          frame=document.getElementById('cw-pdf-frame'),
          obj=document.getElementById('cw-pdf-object'),
          fallback=document.getElementById('cw-pdf-fallback');

    if(window.cwResetPdfRotation) window.cwResetPdfRotation();
    if(window.cwBindPdfPinch) window.cwBindPdfPinch();
    title.textContent=m.name||'Document.pdf';
    pages.innerHTML='';
    viewer.classList.remove('pdf-rendered');
    fallback.style.display='none';
    frame.style.display='none';
    obj.style.display='none';
    loading.style.display='flex';
    viewer.classList.add('open');

    try{
      const pdfjs=await import('https://cdnjs.cloudflare.com/ajax/libs/pdf.js/4.10.38/pdf.min.mjs');
      pdfjs.GlobalWorkerOptions.workerSrc='https://cdnjs.cloudflare.com/ajax/libs/pdf.js/4.10.38/pdf.worker.min.mjs';

