         as a fallback. */
      viewer.classList.remove('pdf-rendered');
      loading.style.display='none';
      frame.style.display='block';
      frame.src=m.src+'#toolbar=1&navpanes=0&scrollbar=0&view=FitH';
      frame.setAttribute('scrolling','no');
      setTimeout(function(){
        if(viewer.classList.contains('open')) fallback.style.display='flex';
      },1800);
    }
  }
