    const s=camSrc(); ctx.fillStyle='#000'; ctx.fillRect(0,0,W,H); if(!s) return;
    const vw=s.videoWidth||s.width, vh=s.videoHeight||s.height, ta=W/H;
    let sw,sh; if(vw/vh>ta){ sh=vh; sw=vh*ta; } else { sw=vw; sh=vw/ta; }
    sw/=cam.zoom; sh/=cam.zoom; const sx=(vw-sw)/2, sy=(vh-sh)/2;
