    if(mir){ ctx.translate(W,0); ctx.scale(-1,1); }
    if(mode==='portrait'){
      /*
       * iPhone-style portrait preview:
       * 1) Render a strongly softened version of the whole frame.
       * 2) Put a sharp, feathered focus area back on top.
       * This keeps the face/subject clear while the surroundings stay
       * smoothly blurred instead of looking pixelated or abruptly masked.
