      fg.imageSmoothingEnabled=true;
      fg.imageSmoothingQuality='high';
      fg.drawImage(s,sx,sy,sw,sh,0,0,W,H);

      fg.globalCompositeOperation='destination-in';
      fg.save();

      const fx=(mir?1-cam.focus.x:cam.focus.x)*W;
      const fy=cam.focus.y*H;
      fg.translate(fx,fy);

      /* Portrait focus shape: tall enough for a face/upper body,
