      fg.scale(1,1.42);
      const R=Math.min(W*.34,H*.28);
      const rg=fg.createRadialGradient(0,0,R*.18,0,0,R);
      rg.addColorStop(0,'rgba(0,0,0,1)');
      rg.addColorStop(.58,'rgba(0,0,0,.99)');
      rg.addColorStop(.78,'rgba(0,0,0,.72)');
      rg.addColorStop(.92,'rgba(0,0,0,.25)');
      rg.addColorStop(1,'rgba(0,0,0,0)');

