  // ---- video: hold = short clip, tap (video modes) = long recording ----
  function recStart(hold){
    if(cam.rec) return;
    const c=$('cam-canvas');
    if(!c.captureStream || !window.MediaRecorder){ showToast('Video recording is not supported here'); return; }
    const out=c.captureStream(cam.mode==='cine'?24:30);
    if(cam.stream) cam.stream.getAudioTracks().forEach(function(t){ out.addTrack(t); });
    let mt=''; ['video/mp4;codecs=avc1','video/webm;codecs=vp9,opus','video/webm;codecs=vp8,opus','video/webm'].some(function(t){ if(MediaRecorder.isTypeSupported(t)){ mt=t; return true; } return false; });
    let mr; try{ mr=new MediaRecorder(out,Object.assign(mt?{mimeType:mt}:{},{videoBitsPerSecond:cam.mode==='cine'?14e6:6e6})); }catch(e){ showToast('Could not start recording'); return; }
    const r={mr:mr,chunks:[],t0:Date.now(),hold:hold,save:true,max:hold?30000:600000,mt:mt};
    mr.ondataavailable=function(e){ if(e.data&&e.data.size) r.chunks.push(e.data); };
    mr.onstop=function(){
      clearInterval(r.tm); out.getVideoTracks().forEach(function(t){ t.stop(); });
      const cl=$('cam-live'); cl.classList.remove('recording','hold','long'); camBadge(); $('cs-c').style.strokeDashoffset=251.3;
      if(!r.save || !r.chunks.length) return;
      cam.video=URL.createObjectURL(new Blob(r.chunks,{type:(mr.mimeType||mt||'video/webm').split(';')[0]}));
      cam.vdur=(Date.now()-r.t0)/1000; cam.shot=null;
      try{ cam.poster=$('cam-canvas').toDataURL('image/jpeg',.8); }catch(e){ cam.poster=null; }
      showCamPreview('video');
    };
    cam.rec=r; mr.start(400);
    $('cam-live').classList.add('recording',hold?'hold':'long');
    r.tm=setInterval(function(){
      const el=Date.now()-r.t0, s=Math.floor(el/1000);
      $('cam-badge').textContent='● '+Math.floor(s/60)+':'+String(s%60).padStart(2,'0');
      if(hold) $('cs-c').style.strokeDashoffset=251.3*(1-Math.min(1,el/r.max));
      if(el>=r.max) recStop();
