  }
  // ---- Snapchat-style capture button ----
  // Tap = photo. Hold = video. While holding, slide finger up/down
  // on the shutter to smoothly zoom in/out.
  (function(){
    const b=$('cam-shutter');
    let t=null, held=false, down=false, pid=null;
    let startY=0, startZoom=1;
    const HOLD_MS=360;

    b.addEventListener('contextmenu',function(e){ e.preventDefault(); });

    b.addEventListener('pointerdown',function(e){
      if(cam.prevw) return;
      down=true; held=false; pid=e.pointerId;
      startY=e.clientY; startZoom=cam.zoom;
      try{ b.setPointerCapture(e.pointerId); }catch(_){}
      if(cam.rec) return;
      t=setTimeout(function(){
        if(!down) return;
        held=true;
        recStart(true);
      },HOLD_MS);
    });

    b.addEventListener('pointermove',function(e){
      if(!down || e.pointerId!==pid || cam.prevw) return;
      const dy=startY-e.clientY;
      // Only activate the vertical zoom gesture once the user is
      // actually holding/recording, keeping a normal tap untouched.
      if(held || cam.rec){
        const next=startZoom*Math.exp(dy*0.006);
