      shoot();
    }

    b.addEventListener('pointerup',finish);
    b.addEventListener('pointercancel',function(e){
      if(!down || (pid!==null && e.pointerId!==pid)) return;
      down=false; clearTimeout(t); t=null;
      try{ if(pid!==null) b.releasePointerCapture(pid); }catch(_){}
      pid=null;
      if(held || cam.rec) recStop();
    });
  })();

