(function(){
  /* In the rotated viewer the browser's native swipe runs along the wrong axes, so this takes over.
     A swipe (either direction on the device) scrolls the document vertically, with a smooth glide;
     while zoomed in, one finger pans freely in both directions. */
  var box=document.getElementById('cw-pdf-pages'), viewer=document.getElementById('cw-pdf-viewer');
  if(!box||!viewer) return;
  var st=null, raf=0, vel=0;
  function rotated(){ return viewer.classList.contains('pdf-screen-landscape'); }
  function zoomed(){ return box.classList.contains('pdf-zoomed'); }
  function stopGlide(){ if(raf){ cancelAnimationFrame(raf); raf=0; } }
  function glide(){
    var last=performance.now();
    (function tick(now){
      var dt=Math.min(32,now-last); last=now;
      var before=box.scrollTop; box.scrollTop+=vel*dt; vel*=Math.pow(.94,dt/16);
      if(Math.abs(vel)<.02||box.scrollTop===before){ raf=0; return; }
      raf=requestAnimationFrame(tick);
    })(last);
  }
  box.addEventListener('touchstart',function(e){
    if(!rotated()){ st=null; return; }
    stopGlide();
    if(e.touches.length===1){
      var t=e.touches[0];
      st={x:t.clientX,y:t.clientY,px:t.clientX,py:t.clientY,axis:'',t:performance.now(),v:0};
      e.stopImmediatePropagation();
    }else st=null;
  },{capture:true,passive:false});
  box.addEventListener('touchmove',function(e){
    if(!st||!rotated()||e.touches.length!==1) return;
    var t=e.touches[0], now=performance.now();
    var dx=t.clientX-st.px, dy=t.clientY-st.py;
    if(zoomed()){
      box.scrollLeft-=dy;      /* device up/down    = reader's left/right */
      box.scrollTop+=dx;       /* device left/right = reader's up/down    */
    }else{
      if(!st.axis){
        if(Math.hypot(t.clientX-st.x,t.clientY-st.y)<6){ e.preventDefault(); e.stopImmediatePropagation(); return; }
        st.axis=Math.abs(t.clientY-st.y)>=Math.abs(t.clientX-st.x)?'v':'h';
