  viewer.addEventListener('touchstart',function(e){
    if(!inPages(e.target)){ tap=null; return; }
    if(e.touches.length!==1){ tap=null; return; }          /* pinch or multi-finger */
    var t=e.touches[0];
    tap={x:t.clientX,y:t.clientY,t:Date.now()};
  },{capture:true,passive:true});
