      me.timers.push(setTimeout(function(){
        if(st!==me) return;
        stopRing(me.ring); me.ring=null; $('thread-call').classList.remove('ringing');
        if(online){ blip(true); startTimer(me); }
        else{
          blip(false); setStatus('No answer'); me.missed=true;
          me.timers.push(setTimeout(function(){ if(st===me) doEnd(true); },1600));
        }
      },(online?3200:8000)-900));
    },900));
  };

  /* ---------- controls ---------- */
  async function flipCamera(){
    if(!st||!hasVideo()||st.flipping) return;
    var cams=[];
    try{ cams=(await navigator.mediaDevices.enumerateDevices()).filter(function(d){return d.kind==='videoinput';}); }catch(e){}
    if(cams.length<2){ showToast('No other camera found'); return; }
    st.flipping=true;
    var me=st, nf=me.facing==='user'?'environment':'user';
    var audio=me.stream.getAudioTracks();
    me.stream.getVideoTracks().forEach(function(t){t.stop();});
    var vt=null;
    try{
      var ns=await navigator.mediaDevices.getUserMedia({video:{facingMode:{ideal:nf}},audio:false});
      vt=ns.getVideoTracks()[0];
    }catch(e){
      try{ var back=await navigator.mediaDevices.getUserMedia({video:{facingMode:{ideal:me.facing}},audio:false}); vt=back.getVideoTracks()[0]; nf=me.facing; }catch(e2){}
      showToast('Couldn\u2019t switch camera');
    }
    if(st!==me||me.ended){ if(vt) vt.stop(); return; }
    if(vt){
      vt.enabled=me.camOn;
      me.stream=new MediaStream(audio.concat([vt]));
      me.facing=nf;
      if(me.pc){ me.pc.getSenders().forEach(function(sn){ if(sn.track&&sn.track.kind==='video'){ try{ sn.replaceTrack(vt); }catch(e){} } }); }
    }
    me.flipping=false;
    var v=$('tc-self'); v.classList.remove('flipping'); void v.offsetWidth; v.classList.add('flipping');
    setTimeout(function(){v.classList.remove('flipping');},520);
    var b=$('tc-flip'); b.classList.remove('spin'); void b.offsetWidth; b.classList.add('spin');
    attachLocal();
  }

  async function turnCameraOn(){
    var me=st; if(!me) return;
    var vt=null;
    try{ var ns=await navigator.mediaDevices.getUserMedia({video:{facingMode:{ideal:me.facing}},audio:false}); vt=ns.getVideoTracks()[0]; }
    catch(e){ showToast('Camera unavailable'); return; }
    if(st!==me||me.ended){ if(vt) vt.stop(); return; }
    var audio=me.stream?me.stream.getAudioTracks():[];
    me.stream=new MediaStream(audio.concat([vt]));
    me.kind='video'; me.camOn=true;
    var ov=$('thread-call'); ov.classList.remove('voice'); ov.classList.add('video');
    $('tc-self').classList.add('pip'); $('tc-remote').classList.remove('pip');
    if(me.pc){
      var vs=me.pc.getTransceivers().find(function(t){return t.receiver&&t.receiver.track&&t.receiver.track.kind==='video'&&!(t.sender&&t.sender.track);});
      if(vs){ vs.sender.replaceTrack(vt); vs.direction='sendrecv'; }
      else me.pc.addTrack(vt,me.stream);
    }
    attachLocal(); setBtn('tc-cam',false);
    if(me.pc) out({type:'cam',call:me.callId,to:me.peer,on:true});
  }

  window.threadCallToggle=function(what){
    if(!st||st.incoming) return;
    if(what==='mute'){
      st.muted=!st.muted;
      if(st.stream) st.stream.getAudioTracks().forEach(function(t){t.enabled=!st.muted;});
      setBtn('tc-mute',st.muted); showToast(st.muted?'Microphone off':'Microphone on');
    }else if(what==='cam'){
      if(!hasVideo()){ turnCameraOn(); return; }
      st.camOn=!st.camOn;
      st.stream.getVideoTracks().forEach(function(t){t.enabled=st.camOn;});
      setBtn('tc-cam',!st.camOn);
      if(st.pc) out({type:'cam',call:st.callId,to:st.peer,on:st.camOn});
    }else if(what==='flip'){
      flipCamera();
    }else if(what==='spk'){
      st.spk=!st.spk; setBtn('tc-spk',st.spk); showToast(st.spk?'Speaker on':'Speaker off');
    }
  };

  /* ---------- end ---------- */
  function doEnd(send,why){
    if(!st||st.ended) return;
    var me=st; me.ended=true; st=null;
    me.timers.forEach(clearTimeout); clearTimeout(me.noAns); if(me.iv) clearInterval(me.iv);
    stopRing(me.ring);
    if(send&&(me.real||me.answered||me.role==='callee')){
      out({type:me.role==='callee'&&!me.answered?'decline':(me.answered?'end':'cancel'),call:me.callId,to:me.peer});
    }
    if(me.pc){ try{ me.pc.close(); }catch(e){} }
    if(me.stream) me.stream.getTracks().forEach(function(t){try{t.stop();}catch(e){}});
    $('tc-self').srcObject=null; $('tc-rv').srcObject=null;
    var ov=$('thread-call');
    ov.classList.remove('show','ringing');
    setTimeout(function(){ if(!st){ ov.classList.remove('open','video','voice','has-cam','swapped','incoming'); ov.setAttribute('aria-hidden','true'); resetTiles(); } },260);
    if(me.answered) blip(false);

    if(me.role==='callee'){
      if(why==='missed') showToast('Missed call');
      else if(why==='ended') showToast('Call ended');
      return;
    }
    if(why==='ended'&&!me.answered) return;
    var label=me.kind==='video'?'Video call':'Voice call', text;
    if(me.answered) text=(me.kind==='video'?'\ud83d\udcf9 ':'\ud83d\udcde ')+label+' \u00b7 '+fmt(me.sec);
    else if(me.declined) text='\ud83d\udcde Declined \u00b7 '+label;
    else if(me.missed) text='\ud83d\udcde No answer \u00b7 '+label;
    else text='\ud83d\udcde Cancelled '+label.toLowerCase();
    try{
      var c=me.chat;
      var st2=me.answered?'done':me.declined?'declined':me.missed?'noanswer':'cancelled';
      c.messages.push({sent:true,text:text,time:'now',_pop:true,call:{kind:me.kind==='video'?'video':'voice',state:st2,dur:me.answered?fmt(me.sec):''}});
      c.preview=text; c.time='now';
      if(typeof renderMessages==='function' && CHATS[activeChatIndex]===c) renderMessages(c);
      if(typeof renderChats==='function') renderChats();
      if(typeof updateList==='function') updateList();
    }catch(e){}
  }
  window.threadEndCall=function(){ doEnd(true); };

  bindPip($('tc-self')); bindPip($('tc-remote'));
  window.addEventListener('pagehide',function(){ if(st) doEnd(true); });
})();

