(function(){
  var BASE='https://fonts.gstatic.com/s/e/notoemoji/latest/';
  var RE;
  try{ RE=/\p{Extended_Pictographic}(?:\ufe0f|[\u{1F3FB}-\u{1F3FF}])?(?:\u200d\p{Extended_Pictographic}(?:\ufe0f|[\u{1F3FB}-\u{1F3FF}])?)*|[\u{1F1E6}-\u{1F1FF}]{2}/gu; }catch(e){ RE=null; }
  function cps(e){ return Array.from(e).map(function(c){ return c.codePointAt(0).toString(16); }).join('_'); }
  function cands(e){
    var a=cps(e), out=[a], bare=a.replace(/_fe0f/g,'');
    if(bare!==a) out.push(bare); else if(Array.from(e).length===1) out.push(a+'_fe0f');
    var noTone=bare.replace(/_?1f3f[b-f]/g,'');
    if(noTone && noTone!==bare && out.indexOf(noTone)<0) out.push(noTone);   /* no skin-tone animation: use the default one */
    return out;
  }
  /* one animated emoji: native emoji shows instantly, the animated version fades in when loaded */
  window.cwAemo=function(e,size,delay){
    var c=cands(e);
    return '<span class="aemo" data-c="'+c.join('|')+'" data-n="0" role="img" aria-label="'+e+'" style="'+(size?'--s:'+size+'px;':'')+(delay?'--d:'+delay+';':'')+'">'
      +'<span class="d3"><span class="fb" aria-hidden="true">'+e+'</span>'
      +'<img alt="" decoding="async" loading="lazy" draggable="false" src="'+BASE+c[0]+'/512.webp" onload="this.parentNode.parentNode.classList.add(\'ld\')" onerror="cwAemoErr(this)">'
      +'</span></span>';
  };
  window.cwAemoErr=function(img){
    var p=img.parentNode.parentNode, c=(p.getAttribute('data-c')||'').split('|'), n=(+p.getAttribute('data-n')||0)+1;
    if(n<c.length){ p.setAttribute('data-n',n); img.src=BASE+c[n]+'/512.webp'; }
    else { img.style.display='none'; p.classList.add('err'); }
  };
  window.cwAnimEmo=function(t){
    t=String(t||''); var m=RE?(t.match(RE)||[]):[];
    if(!m.length) return t;
    return '<span class="aemo-row">'+m.map(function(e,i){ return cwAemo(e,0,i); }).join('')+'</span>';
  };

  /* ===== copy fix ===== */
  function plain(raw){
    var s=String(raw||'').replace(/<br\s*\/?>/gi,'\n').replace(/<[^>]*>/g,'');
    var d=document.createElement('textarea'); d.innerHTML=s; return d.value;   /* decode &amp; &lt; ... */
  }
  /* works without focusing any input (so the in-app keyboard never pops up) */
  function legacyCopy(t){
    var ok=false, el=document.createElement('div');
    try{
      el.textContent=t;
      el.style.cssText='position:fixed;left:0;top:0;opacity:0;white-space:pre-wrap;-webkit-user-select:text;user-select:text;pointer-events:none;z-index:-1';
      document.body.appendChild(el);
      var sel=window.getSelection(), keep=(sel&&sel.rangeCount)?sel.getRangeAt(0):null, r=document.createRange();
      r.selectNodeContents(el); sel.removeAllRanges(); sel.addRange(r);
      ok=document.execCommand('copy');
      sel.removeAllRanges(); if(keep) sel.addRange(keep);
    }catch(e){ ok=false; }
    if(el.parentNode) el.parentNode.removeChild(el);
    return ok;
  }
  function copyText(t){
    return new Promise(function(done){
      if(legacyCopy(t)) return done(true);                       /* sync, inside the tap */
      try{
        if(navigator.clipboard && navigator.clipboard.writeText){
          navigator.clipboard.writeText(t).then(function(){ done(true); },function(){ done(false); }); return;
        }
      }catch(e){}
      done(false);
    });
  }
  window.cwCopyText=copyText;
  window.cwCopyAction=function(){
    var c=CHATS[activeChatIndex], m=c&&c.messages[cwActionIndex];
    var t=m?plain(m.text||m.caption||''):'';
    cwHideActions();
    if(!t){ showToast('Nothing to copy'); return; }
    copyText(t).then(function(ok){ showToast(ok?'Copied':'Couldn\u2019t copy \u2013 allow clipboard access'); });
  };
})();

