(function(){
  var RE; try{ RE=/\p{Extended_Pictographic}(?:\ufe0f|[\u{1F3FB}-\u{1F3FF}])?(?:\u200d\p{Extended_Pictographic}(?:\ufe0f|[\u{1F3FB}-\u{1F3FF}])?)*|[\u{1F1E6}-\u{1F1FF}]{2}/gu; }catch(e){ return; }
  var busy=false;
  function convert(root){
    if(busy||typeof cwAemo!=='function') return;
    busy=true;
    try{
      var tw=document.createTreeWalker(root,NodeFilter.SHOW_TEXT,null), nodes=[], n;
      while((n=tw.nextNode())){
        var p=n.parentNode; if(!p||!p.closest) continue;
        if(p.closest('.aemo,.msg-time,script,style,textarea')) continue;
        if(!p.closest('.msg')) continue;
        RE.lastIndex=0; if(RE.test(n.nodeValue)) nodes.push(n);
      }
      nodes.forEach(function(t){
        var txt=t.nodeValue, frag=document.createDocumentFragment(), last=0, m, k=0;
        RE.lastIndex=0;
        while((m=RE.exec(txt))){
          if(m.index>last) frag.appendChild(document.createTextNode(txt.slice(last,m.index)));
          var w=document.createElement('span'); w.innerHTML=cwAemo(m[0],0,k++);
          var el=w.firstChild; el.classList.add('inl'); el.style.removeProperty('--s'); frag.appendChild(el);
          last=m.index+m[0].length;
        }
        if(last<txt.length) frag.appendChild(document.createTextNode(txt.slice(last)));
        t.parentNode.replaceChild(frag,t);
      });
    }catch(e){}
    busy=false;
  }
  function init(){
    var wrap=document.getElementById('cw-messages'); if(!wrap) return setTimeout(init,300);
    new MutationObserver(function(){ convert(wrap); }).observe(wrap,{childList:true,subtree:true});
    convert(wrap);
  }
  if(document.readyState==='loading') document.addEventListener('DOMContentLoaded',init); else init();
})();

(function(){
  /* ===== fake friend: comes online, types, replies, then goes offline with "last seen" ===== */
  var R={
    hi:['Hey! 👋','Hi there 😊','Heyy, how are you?'],
    how:['All good, you? 🙂','Pretty good, just busy today','Can\'t complain 😄'],
    thanks:['Anytime! 🙌','No problem 😊','Of course!'],
    q:['Hmm, let me check and tell you','Good question 🤔 I think yes','Probably, I\'ll confirm in a bit','Yes, that works for me 👍'],
    ok:['Great! 👍','Perfect 🙌','Sounds good!','Done 😄'],
    bye:['Talk later! 👋','Bye 😊','See you soon!'],
    love:['Aww 🥰','Haha love that ❤️'],
    gen:['Haha okay 😄','Got it 👍','Oh nice!','Wait, really? 😮','Give me 5 mins','On my way 🙌','Tell me more!'],
    photo:['Nice pic! 😍','Wow, love this 📸','Haha great shot!'],
    video:['Just watched it 😂','That video 🔥','Haha send more!'],
    voice:['Got your voice note 🎧','Listening now… 🎧','Haha your voice 😄'],
    file:['Got the file, thanks! 📄','Received 👍 I\'ll take a look','Thanks, opening it now'],
    emoji:['😄','🙌','😂','❤️']
  };
  function pick(a){ return a[Math.floor(Math.random()*a.length)]; }
  function strip(h){ return String(h||'').replace(/<[^>]*>/g,' ').trim(); }
  function choose(m){
    var t=m&&m.type;
    if(t==='img'||t==='gif') return pick(R.photo);
    if(t==='video') return pick(R.video);
    if(t==='voice') return pick(R.voice);
    if(t==='file') return pick(R.file);
    if(t==='stk') return pick(R.emoji);
    var x=strip(m&&m.text).toLowerCase();
    if(!x) return pick(R.gen);
    try{ if(typeof cwEmojiOnly==='function'&&cwEmojiOnly(m.text)) return pick(R.emoji); }catch(e){}
    if(/\b(bye|goodnight|good night|gn|cya|see you|ttyl)\b/.test(x)) return pick(R.bye);
    if(/\b(thanks|thank you|thx|ty)\b/.test(x)) return pick(R.thanks);
    if(/\b(love you|miss you|luv)\b/.test(x)) return pick(R.love);
    if(/^(hi|hey|hello|hii+|yo|sup|hola)\b/.test(x)) return pick(R.hi);
    if(/how are you|how r u|how('s| is) it going|what'?s up|wassup/.test(x)) return pick(R.how);
    if(/\b(ok|okay|sure|fine|done|cool|great)\b/.test(x)&&x.length<20) return pick(R.ok);
    if(x.indexOf('?')>=0) return pick(R.q);
    return pick(R.gen);
  }
  function refresh(c){
    try{
      var i=CHATS.indexOf(c);
      if(i===activeChatIndex){
        var st=document.getElementById('cw-status');
        if(st&&!c.typing) st.textContent=cwLastSeenText(c);
      }
      renderChats(); updateList();
    }catch(e){}
  }
  function clear(c){ (c._fk||[]).forEach(clearTimeout); c._fk=[]; }
  function later(c,ms,fn){ c._fk.push(setTimeout(fn,ms)); }
  window.cwDemoReply=function(c,msg){
    if(!c||window.CW_DEMO_REPLY===false) return;
    var i=CHATS.indexOf(c); if(i<0) return;
    clear(c); clearTimeout(c._rt);
    if(c._wasOnline===undefined) c._wasOnline=!!c.online;
    var reply=choose(msg||(c.messages&&c.messages[c.messages.length-1])||{});
    var wait=0;
    if(!c.online){                                  /* friend was offline: shows "last seen …", then comes online */
      wait=1400+Math.random()*1200;
      later(c,wait,function(){ c.online=true; refresh(c); });
      wait+=900;
    } else wait=600+Math.random()*500;
    later(c,wait,function(){ cwSetTyping(i,true); });
    var typeMs=1200+Math.min(reply.length,40)*55;
    later(c,wait+typeMs,function(){
      cwSetTyping(i,false); cwReceiveMessage(i,{text:reply});
      if(!c._wasOnline){                            /* goes offline again a few seconds later -> "last seen just now" */
        later(c,9000+Math.random()*4000,function(){
          c.online=false; c.lastSeen=Date.now(); c._wasOnline=undefined; refresh(c);
        });
      } else c._wasOnline=undefined;
    });
  };
  /* replies to photos, videos, voice notes, files, stickers and GIFs too */
  if(typeof cwPush==='function'){
    var _push=cwPush;
    window.cwPush=function(m){ _push.apply(this,arguments); try{ cwDemoReply(CHATS[activeChatIndex],m); }catch(e){} };
  }
  /* keep the header status fresh ("last seen 2 min ago") */
  setInterval(function(){
    try{
      var sc=document.getElementById('screen-chatwindow'), c=CHATS[activeChatIndex];
      if(sc&&sc.classList.contains('active')&&c&&!c.typing){ var st=document.getElementById('cw-status'); if(st) st.textContent=cwLastSeenText(c); }
    }catch(e){}
  },15000);
})();

