document.addEventListener('change',function(e){
  var el=e.target; if(!el||el.type!=='file'||!el.files||!el.files.length) return;
  var max=T.limit('file'), cap=max*1048576, i, f;
  for(i=0;i<el.files.length;i++){ f=el.files[i]; if(f.size>cap){
    e.stopImmediatePropagation(); try{ el.value=''; }catch(_){}
    var P=cfg().premium, up=(!T.isPro()&&T.perkOn('long')&&P.lim.file>max);
    toast('That file is over '+max+' MB'+(up?' \u00B7 Plus allows '+P.lim.file+' MB':'')); if(up) setTimeout(function(){ T.openPlus('Bigger uploads'); },700);
    return; } }
},true);
