      if(!m||m.call) return;
      if((m.type==='img'||m.type==='gif')&&m.src) out.push({j:j,k:m.type==='gif'?'gif':'img',src:m.src});
      else if(m.type==='video'&&m.src) out.push({j:j,k:'video',src:m.src});
    }); return out;
  }
  var URL_RE=/(https?:\/\/[^\s<>"']+|www\.[^\s<>"']+)/gi;
  function linkItems(c){
    var out=[]; (c.messages||[]).forEach(function(m,j){
      if(!m||m.call) return;
      var t=plain(m.text)+' '+plain(m.caption), f=t.match(URL_RE);
      if(f) f.forEach(function(u){ out.push({j:j,url:u.replace(/[.,;:!?)]+$/,''),time:m.time}); });
    }); return out;
  }
  function docItems(c){
    var out=[]; (c.messages||[]).forEach(function(m,j){ if(m&&m.type==='file') out.push({j:j,name:m.name||'Document',size:m.size,time:m.time,ext:((String(m.name||'').match(/\.([a-z0-9]{1,5})$/i)||[])[1]||'FILE').toUpperCase()}); });
    return out;
  }
  function fsize(b){ b=+b||0; return b<1024?b+' B':b<1048576?(b/1024).toFixed(0)+' KB':(b/1048576).toFixed(1)+' MB'; }

  function jump(j,openIt){
    close();
    setTimeout(function(){
      var t=document.querySelector('#cw-messages [data-mi="'+j+'"]'); if(!t) return;
      try{ t.scrollIntoView({block:'center',behavior:'smooth'}); }catch(e){}
      t.classList.remove('cw-hl'); void t.offsetWidth; t.classList.add('cw-hl'); setTimeout(function(){ t.classList.remove('cw-hl'); },1400);
      if(openIt) setTimeout(function(){ try{ t.click(); }catch(e){} },450);
    },220);
  }

  /* ---- views ---- */
  function head(title,back){
    return '<div class="cwm-h">'+(back?'<button class="cwm-ib" data-a="back" aria-label="Back">'+IC.back+'</button>':'')+'<b>'+esc(title)+'</b><button class="cwm-ib" data-a="close" aria-label="Close">'+IC.x+'</button></div>';
  }
  function row(a,ic,t,s,cls){ return '<div class="cwm-row '+(cls||'')+'" data-a="'+a+'" role="button" tabindex="0"><span class="cwm-ic">'+ic+'</span><span class="cwm-tx"><b>'+t+'</b>'+(s?'<small>'+s+'</small>':'')+'</span>'+IC.chev+'</div>'; }

  function render(){
    var c=chat(); if(!c){ card.innerHTML=head('Chat',false)+'<div class="cwm-empty">Open a chat first.</div>'; return; }
    var name=c.name||'Chat', pr=pref(name), h='';
    if(view==='main'){
      var mi=mediaItems(c).length, li=linkItems(c).length, di=docItems(c).length;
      h=head(name,false)+'<div class="cwm-b">'
        +row('media',IC.media,'Media',mi?mi+' photo'+(mi===1?'':'s')+' & videos':'Photos, videos and GIFs')
        +row('links',IC.link,'Links and docs',(li||di)?li+' link'+(li===1?'':'s')+' · '+di+' doc'+(di===1?'':'s'):'Shared links and files')
        +row('dis',IC.timer,'Disappearing messages',durLabel(c.disappear))
        +'<div class="cwm-sep"></div>'
        +row('more',IC.more,'More options','Report, block, clear chat')
        +'</div>';
    } else if(view==='more'){
      h=head('More options',true)+'<div class="cwm-b">'
        +row('report',IC.flag,'Report','Tell us what is wrong')
        +row(c.blocked?'unblock':'block',IC.block,c.blocked?'Unblock':'Block',c.blocked?'Allow messages and calls again':'Stop messages and calls','danger')
        +row('clear',IC.trash,'Clear chat','Delete all messages here','danger')
        +'</div>';
    } else if(view==='media'){
      var it=mediaItems(c);
      h=head('Media',true)+'<div class="cwm-b">'+(it.length?'<div class="cwm-grid">'+it.map(function(x){
        return '<div class="cwm-th" data-j="'+x.j+'" data-o="'+(x.k==='video'?0:1)+'">'+(x.k==='video'?'<video src="'+esc(x.src)+'#t=0.1" muted playsinline preload="metadata"></video>'+IC.play:'<img src="'+esc(x.src)+'" alt="" loading="lazy">'+(x.k==='gif'?'<i>GIF</i>':''))+'</div>';
      }).join('')+'</div>':'<div class="cwm-empty">No photos or videos shared yet.</div>')+'</div>';
    } else if(view==='links'){
      var L=linkItems(c), D=docItems(c);
      h=head('Links and docs',true)+'<div class="cwm-b"><div class="cwm-tabs"><button data-t="links" class="'+(tabSel==='links'?'on':'')+'">Links ('+L.length+')</button><button data-t="docs" class="'+(tabSel==='docs'?'on':'')+'">Docs ('+D.length+')</button></div>';
      if(tabSel==='links') h+=L.length?L.map(function(x){
        return '<div class="cwm-row" data-u="'+esc(x.url)+'" data-j="'+x.j+'" role="button"><span class="cwm-ic">'+IC.link+'</span><span class="cwm-tx"><b style="font-size:14px;color:var(--coral,#e8604c)">'+esc(x.url.replace(/^https?:\/\//i,'').slice(0,34))+'</b><small class="ln">'+esc(x.url)+'</small></span></div>';
      }).join(''):'<div class="cwm-empty">No links shared yet.</div>';
      else h+=D.length?D.map(function(x){
        return '<div class="cwm-row" data-d="'+x.j+'" role="button"><span class="cwm-ext">'+esc(x.ext.slice(0,4))+'</span><span class="cwm-tx"><b style="font-size:14px">'+esc(x.name)+'</b><small>'+(x.size?fsize(x.size)+' · ':'')+esc(x.time||'')+'</small></span></div>';
      }).join(''):'<div class="cwm-empty">No documents shared yet.</div>';
      h+='</div>';
    } else if(view==='dis'){
      h=head('Disappearing messages',true)+'<div class="cwm-b">'+DUR.map(function(d){
        return '<div class="cwm-opt '+((c.disappear||0)===d[1]?'on':'')+'" data-ms="'+d[1]+'" role="button"><span>'+d[0]+'</span><i class="cwm-rd"></i></div>';
      }).join('')+'<div class="cwm-note">New messages in this chat will disappear after the time you choose. Messages already here stay.</div></div>';
    } else if(view==='block'){
      h=head('Block',true)+'<div class="cwm-b"><div class="cwm-conf"><div class="big">'+IC.block+'</div><h4>Block '+esc(name)+'?</h4><p>They will not be able to message or call you, and you will not receive their messages. You can unblock anytime.</p><div class="cwm-btns"><button data-a="more">Cancel</button><button class="red" data-a="doblock">Block</button></div></div></div>';
    } else if(view==='clear'){
      h=head('Clear chat',true)+'<div class="cwm-b"><div class="cwm-conf"><div class="big">'+IC.trash+'</div><h4>Clear this chat?</h4><p>All messages in your chat with '+esc(name)+' will be deleted from this device.</p><div class="cwm-btns"><button data-a="more">Cancel</button><button class="red" data-a="doclear">Clear chat</button></div></div></div>';
    }
    card.innerHTML=h;
  }

  /* ---- actions ---- */
  function applyState(){
    var c=chat(); if(!c) return;
    var pr=pref(c.name);
    if(pr.blocked!==undefined) c.blocked=!!pr.blocked;
    if(pr.dis!==undefined&&c.disappear===undefined){ c.disappear=pr.dis; if(pr.dis>0) (c.messages||[]).forEach(function(m){ if(m&&!m._ts) m._keep=true; }); }
    scr.classList.toggle('cw-blocked',!!c.blocked);
    btn.classList.toggle('has-dis',!!c.disappear);
  }
  function setDisappear(ms){
    var c=chat(); if(!c) return;
    c.disappear=ms; pref(c.name).dis=ms; savePrefs();
    if(ms>0){ (c.messages||[]).forEach(function(m){ if(m&&!m._ts) m._keep=true; }); }
    applyState();
    toast(ms>0?'Disappearing messages: '+durLabel(ms):'Disappearing messages turned off');
    view='main'; render();
  }
  function setBlocked(v){
    var c=chat(); if(!c) return;
    c.blocked=v; pref(c.name).blocked=v; savePrefs(); applyState();
    try{ if(v){ c.typing=false; } }catch(e){}
    toast(v?(c.name+' blocked'):(c.name+' unblocked'));
  }
  function clearChat(){
    var c=chat(); if(!c) return;
    c.messages=[]; c.preview='No messages'; c.unread=0; c.typing=false;
    delete c.previewType; delete c.previewExt; c.sent=false;
    try{ window.threadCw.render(); window.threadCw.list(); }catch(e){}
    toast('Chat cleared');
  }

  card.addEventListener('click',function(e){
    var t=e.target, el;
    if((el=t.closest('[data-ms]'))){ setDisappear(+el.getAttribute('data-ms')); return; }
    if((el=t.closest('[data-t]'))){ tabSel=el.getAttribute('data-t'); render(); return; }
    if((el=t.closest('.cwm-th'))){ jump(+el.getAttribute('data-j'),el.getAttribute('data-o')==='1'); return; }
    if((el=t.closest('[data-u]'))){ var u=el.getAttribute('data-u'); if(!/^https?:/i.test(u)) u='https://'+u; try{ window.open(u,'_blank','noopener'); }catch(x){} return; }
    if((el=t.closest('[data-d]'))){ jump(+el.getAttribute('data-d'),true); return; }
    if((el=t.closest('[data-a]'))){
      var a=el.getAttribute('data-a');
      if(a==='close'){ close(); return; }
      if(a==='back'){ view=(view==='block'||view==='clear')?'more':'main'; render(); return; }
      if(a==='media'||a==='links'||a==='dis'||a==='more'||a==='block'||a==='clear'){ view=a; render(); return; }
      if(a==='report'){
        var c=chat(); close();
        setTimeout(function(){ try{ window.TPX.report('Chat',c&&c.name); }catch(x){ toast('Report sent'); } },200); return;
      }
      if(a==='unblock'){ setBlocked(false); view='more'; render(); return; }
      if(a==='doblock'){ setBlocked(true); close(); return; }
      if(a==='doclear'){ clearChat(); close(); return; }
    }
  });
  card.addEventListener('keydown',function(e){ if((e.key==='Enter'||e.key===' ')&&e.target.matches('[data-a]')){ e.preventDefault(); e.target.click(); } });
  var ub=$('cw-unblock'); if(ub) ub.addEventListener('click',function(){ setBlocked(false); });

  /* ---- keep state in sync when a chat opens ---- */
  var _oc=window.openChat;
  if(typeof _oc==='function') window.openChat=function(){ var r=_oc.apply(this,arguments); try{ close(); applyState(); }catch(e){} return r; };

  /* ---- blocked contacts cannot deliver new messages ---- */
  var _rm=window.cwReceiveMessage;
  if(typeof _rm==='function') window.cwReceiveMessage=function(ix,m){
    try{ var cs=window.threadChats(); if(cs&&cs[ix]&&cs[ix].blocked) return; }catch(e){}
    return _rm.apply(this,arguments);
  };

  /* ---- disappearing messages: purge expired ones ---- */
  setInterval(function(){
    var cs; try{ cs=window.threadChats(); }catch(e){ return; } if(!cs) return;
    var act=chat(), now=Date.now(), touched=false, listDirty=false;
    cs.forEach(function(c){
      if(!c.disappear||!c.messages) return;
      var before=c.messages.length;
      c.messages=c.messages.filter(function(m){
        if(!m||m._keep) return true;
        if(!m._ts) m._ts=now;
        return now-m._ts<c.disappear;
      });
      if(c.messages.length!==before){ listDirty=true; if(c===act) touched=true;
        var last=c.messages[c.messages.length-1];
        if(!last){ c.preview='No messages'; delete c.previewType; delete c.previewExt; }
      }
    });
    if(touched){ try{ window.threadCw.render(); }catch(e){} if(ov.classList.contains('open')) render(); }
    if(listDirty){ try{ window.threadCw.list(); }catch(e){} }
  },1000);

  applyState();
})();

/* Following count on your own profile = accounts you really follow (starts at 0). */
(function(){
  function real(){ var n=0; try{ Object.keys(USERS).forEach(function(h){ if(h!=='priya.patel'&&USERS[h]&&USERS[h].following) n++; }); }catch(e){ return null; } return n; }
  function sync(){ var n=real(), e=document.getElementById('pf-following'); if(e&&n!==null) e.textContent=n.toLocaleString('en-US'); }
  var t=window.toggleFollow;
  if(typeof t==='function') window.toggleFollow=function(){ var r=t.apply(this,arguments); setTimeout(sync,0); return r; };
  var u=window.flUnfollow;
  if(typeof u==='function') window.flUnfollow=function(){ var r=u.apply(this,arguments); setTimeout(sync,0); return r; };
})();
